ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns ns0 https://itmo.ru/humanbeings/service
---
{
  ns0#getHumanBeings: {
    queryRequest: {
      sortParameters: {
        (attributes.queryParams.*sort map ((item) -> sortParameter: item))
      },
      filterParameters: {
        (attributes.queryParams.*filter map ((item) -> filterParameter: item))
      },
      page: (attributes.queryParams.page as Number default 1) as Number,
      pageSize: (attributes.queryParams.pageSize as Number default 10) as Number
    }
  }
}

%dw 2.0
output application/xml
ns ns0 https://itmo.ru/humanbeings/service
---
{
  ns0#addHumanBeing: {
    humanBeingRequest: {
      name: payload.name,
      coordinates: {
        x: payload.coordinates.x as Number,
        y: payload.coordinates.y as Number
      },
      realHero: payload.realHero as Boolean,
      hasToothpick: payload.hasToothpick as Boolean,
      impactSpeed: payload.impactSpeed as Number,
      weaponType: payload.weaponType,
      mood: payload.mood,
      teamId: if (payload.teamId != null) payload.teamId as Number else null,
      (if (payload.car? and payload.car != null) car: {
        cool: payload.car.cool as Boolean,
        color: payload.car.color,
        model: payload.car.model
      } else {})
    }
  }
}

%dw 2.0
output application/xml
ns ns0 https://itmo.ru/humanbeings/service
---
{
  ns0#getHumanBeing: {
    id: attributes.uriParams.id as Number
  }
}

%dw 2.0
output application/xml
ns ns0 https://itmo.ru/humanbeings/service
---
{
  ns0#updateHumanBeing: {
    id: attributes.uriParams.id as Number,
    humanBeingRequest: {
      name: payload.name,
      coordinates: {
        x: payload.coordinates.x as Number,
        y: payload.coordinates.y as Number
      },
      realHero: payload.realHero as Boolean,
      hasToothpick: payload.hasToothpick as Boolean,
      impactSpeed: payload.impactSpeed as Number,
      weaponType: payload.weaponType,
      mood: payload.mood,
      teamId: if (payload.teamId != null) payload.teamId as Number else null,
      (if (payload.car? and payload.car != null) car: {
        cool: payload.car.cool as Boolean,
        color: payload.car.color,
        model: payload.car.model
      } else {})
    }
  }
}

%dw 2.0
output application/xml
ns ns0 https://itmo.ru/humanbeings/service
---
{
  ns0#deleteHumanBeing: {
    id: attributes.uriParams.id as Number
  }
}

%dw 2.0
output application/xml
ns ns0 https://itmo.ru/humanbeings/service
---
{
  ns0#getUniqueImpactSpeeds: {}
}

%dw 2.0 output application/json
var soapErrorPayload = error.errorMessage.payload default null var faultDetail = soapErrorPayload.cause.cause.cause.errorMessage.payload.Envelope.Body.Fault.detail default null
--- if (faultDetail != null) { "code": faultDetail.humanBeingServiceFault.code, "message": faultDetail.humanBeingServiceFault.message, "time": faultDetail.humanBeingServiceFault.timestamp } else { "code": 500, "message": "Unexpected error", "time": now() }
